-- C-04: shared purchase entry points and purchase-order approval lifecycle.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema purchase_order_private;
revoke all on schema purchase_order_private from public,anon,authenticated,service_role;
grant usage on schema purchase_order_private to authenticated;
create function purchase_order_private.resource(k text) returns text language sql immutable set search_path=pg_catalog as $$select case k when 'ORDER' then 'purchasing:orders' when 'QUOTE' then 'purchasing:quotes' when 'REQUISITION' then 'purchasing:requisitions' when 'RECEIPT' then 'purchasing:goods-receipts' end$$;
create function purchase_order_private.allowed(k text,a text) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform asset_posting_private.identity();return purchase_order_private.resource(k) is not null and asset_posting_private.allowed(purchase_order_private.resource(k),a);exception when insufficient_privilege then return false;end$$;
create function purchase_order_private.access(k text,a text) returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin
 if not purchase_order_private.allowed(k,a) then raise exception using errcode='42501',message='El rol activo no puede realizar esta accion en Compras.';end if;return sid;end$$;
create function purchase_order_private.visible(id bigint) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 return exists(select 1 from public.purchase_document d where d.document_id=id and d.subsidiary_id=asset_posting_private.identity() and purchase_order_private.allowed(d.document_type,'view'));exception when insufficient_privilege then return false;end$$;
create function purchase_order_private.header(id bigint,a text) returns public.purchase_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document%rowtype;sid bigint:=asset_posting_private.identity();begin
 select * into d from public.purchase_document where document_id=id and subsidiary_id=sid for update;
 if d.document_id is null then raise exception using errcode='42501',message='Documento no disponible.';end if;perform purchase_order_private.access(d.document_type,a);return d;end$$;
create function purchase_order_private.editable(d public.purchase_document) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if d.document_type='ORDER' and (not exists(select 1 from public."transaction" t join public.transaction_types tt using(transaction_type_id) where t.transaction_id=d.transaction_id and t.subsidiary_id=d.subsidiary_id and tt.abbreviation='ORD_COM' and t.currency_id=d.currency_id and t.exchange_rate=d.exchange_rate and t.tran_date=d.document_date and t.total_amount=d.total_amount and t.fiscal_period_id=d.fiscal_period_id) or exists(select 1 from public.gl_impact where transaction_id=d.transaction_id) or exists(select 1 from public.stock_movements where transaction_id=d.transaction_id)) then raise exception using errcode='55000',message='El origen operativo de la orden requiere revision.';end if;
 if d.document_type='ORDER' and (d.status not in('BORRADOR','RECHAZADO') or exists(select 1 from public.wf_instances where entity_type='PURCHASE_ORDER' and entity_id=d.document_id and status not in('BORRADOR','RECHAZADO')))
 or exists(select 1 from public.purchase_document where source_document_id=d.document_id)
 or exists(select 1 from public.supplier_invoice where purchase_receipt_document_id=d.document_id or po_id=d.document_id)
 then raise exception using errcode='55000',message='El documento tiene aprobacion o documentos posteriores; conserva su historial.';end if;
end$$;
alter function public.save_purchase_document_without_budget(jsonb,bigint) set schema purchase_order_private;
alter function public.purchase_workflow_options() set schema purchase_order_private;
alter function public.purchase_document_report(jsonb) set schema purchase_order_private;
alter function public.purchase_document_detail(bigint) set schema purchase_order_private;
alter function public.delete_purchase_document(bigint) set schema purchase_order_private;
-- Shared writer: preserve engine but validate and normalize its authoritative input first.
create function purchase_order_private.prepare(p jsonb,id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare k text:=p->>'type';sid bigint;d public.purchase_document%rowtype;src public.purchase_document%rowtype;l jsonb;lines jsonb:='[]';n numeric;c numeric;t numeric;tax_id bigint;product public.products%rowtype;begin
 sid:=purchase_order_private.access(k,case when id is null then 'create' else 'edit' end);
 if p is null or jsonb_typeof(p)<>'object' or jsonb_typeof(p->'lines') is distinct from 'array' or jsonb_array_length(p->'lines') not between 1 and 500 then raise exception using errcode='22023',message='El documento requiere entre 1 y 500 lineas.';end if;
 if p ?| array['transaction_id','document_number','created_by','journal_id','is_opening_balance'] or (p?'subsidiary_id' and (p->>'subsidiary_id')::bigint is distinct from sid) then raise exception using errcode='42501',message='No puede sustituir el origen o subsidiaria.';end if;
 if id is not null then d:=purchase_order_private.header(id,'edit');if d.document_type<>k then raise exception using errcode='42501',message='El tipo del documento no puede cambiar.';end if;perform purchase_order_private.editable(d);end if;
 if k='ORDER' and coalesce(p->>'status','BORRADOR')<>'BORRADOR' then raise exception using errcode='42501',message='La aprobacion requiere el flujo autorizado.';end if;
 perform supplier_invoice_private.period((p->>'period_id')::bigint,(p->>'date')::date);
 if not isfinite((p->>'date')::date) or not asset_posting_private.finite((p->>'rate')::numeric) or (p->>'rate')::numeric<=0 or ((p->>'currency_id')::bigint=(select currency_id from public.subsidiaries where subsidiary_id=sid) and (p->>'rate')::numeric<>1) then raise exception using errcode='22023',message='Fecha o tipo de cambio invalido.';end if;
 if k<>'REQUISITION' or nullif(p->>'supplier_id','') is not null then
 if not exists(select 1 from public.suppliers s join public.entity_subsidiaries es using(supplier_id) where s.supplier_id=nullif(p->>'supplier_id','')::bigint and es.subsidiary_id=sid and not s.is_inactive) then raise exception using errcode='42501',message='Proveedor no disponible.';end if;end if;
 if nullif(p->>'payment_term_id','') is not null and not exists(select 1 from public.payment_terms where term_id=(p->>'payment_term_id')::bigint) then raise exception using errcode='22023',message='Termino de pago invalido.';end if;
 if nullif(p->>'source_id','') is not null then
  select * into src from public.purchase_document where document_id=(p->>'source_id')::bigint and subsidiary_id=sid for update;
  if src.document_id is null or src.document_id=id or src.document_type is distinct from (case k when 'QUOTE' then 'REQUISITION' when 'ORDER' then 'QUOTE' when 'RECEIPT' then 'ORDER' end) or src.status='CANCELADO' or (src.supplier_id is not null and src.supplier_id is distinct from nullif(p->>'supplier_id','')::bigint) or src.currency_id is distinct from (p->>'currency_id')::bigint then raise exception using errcode='42501',message='Documento origen incompatible.';end if;
 end if;
 for l in select value from jsonb_array_elements(p->'lines') loop
  n:=(l->>'quantity')::numeric;c:=(l->>'unit_cost')::numeric;
  if jsonb_typeof(l)<>'object' or not asset_posting_private.finite(n) or n<=0 or not asset_posting_private.finite(c) or c<0 then raise exception using errcode='22023',message='Cantidad y costo deben ser finitos y validos.';end if;
  select * into product from public.products where product_id=nullif(l->>'product_id','')::bigint;
  if product.product_id is null or not product.is_active or product.product_usage not in('Compra','Ambas') or not exists(select 1 from public.product_subsidiaries ps where ps.product_id=product.product_id and ps.subsidiary_id=sid and ps.is_active) or product.purchase_account_id is distinct from nullif(l->>'account_id','')::bigint then raise exception using errcode='42501',message='Articulo o cuenta de compra no disponible.';end if;
  perform asset_posting_private.account(product.purchase_account_id);
  perform asset_posting_private.dimensions(nullif(l->>'department_id','')::bigint,nullif(l->>'cost_center_id','')::bigint,nullif(l->>'class_id','')::bigint);
  if nullif(l->>'financial_creditor_id','') is not null or nullif(l->>'related_company_id','') is not null then raise exception using errcode='42501',message='Estas dimensiones requieren un proceso contable especifico.';end if;
  tax_id:=nullif(l->>'tax_code_id','')::bigint;t:=0;
  if tax_id is not null then select tc.rate_percentage into t from public.tax_codes tc join public.tax_types tt using(tax_type_id) where tc.tax_code_id=tax_id and not tc.is_withholding and tt.applies_to in('Compras','Ambos') and exists(select 1 from public.tax_code_subsidiaries ts where ts.tax_code_id=tc.tax_code_id and ts.subsidiary_id=sid);
   if not found then raise exception using errcode='42501',message='Impuesto de compra no autorizado.';end if;end if;
  if not asset_posting_private.finite(t) or t not between 0 and 100 or (l?'tax_rate' and (l->>'tax_rate')::numeric is distinct from t) then raise exception using errcode='22023',message='La tasa debe coincidir con el impuesto configurado.';end if;
  lines:=lines||jsonb_build_array(l||jsonb_build_object('tax_rate',t));
 end loop;
 return p||jsonb_build_object('lines',lines,'status',case when k='ORDER' then 'BORRADOR' else coalesce(p->>'status','BORRADOR') end);
end$$;
create function purchase_order_private.engine(p jsonb,id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare result jsonb;d public.purchase_document%rowtype;v jsonb:=purchase_order_private.prepare(p,id);old_guard text:=current_setting('nexo.purchase_order_id',true);begin
 if p->>'type'='ORDER' and id is not null then perform set_config('nexo.purchase_order_id',id::text,true);end if;
 result:=purchase_order_private.save_purchase_document_without_budget(v,id);
 select * into d from public.purchase_document where document_id=(result->>'id')::bigint;
 -- The old writer updates only transaction date/total. Keep its linked header consistent too.
 update public."transaction" set currency_id=d.currency_id,exchange_rate=d.exchange_rate,fiscal_period_id=d.fiscal_period_id,supplier_id=d.supplier_id,payment_term_id=d.payment_term_id where transaction_id=d.transaction_id and subsidiary_id=d.subsidiary_id;
 perform set_config('nexo.purchase_order_id',coalesce(old_guard,''),true);return result;end$$;
create or replace function public.save_purchase_document(p_payload jsonb,p_document_id bigint default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform purchase_order_private.access(p_payload->>'type',case when p_document_id is null then 'create' else 'edit' end);return public.budget_run('ORD_COM',p_payload,p_document_id);end$$;
create function public.purchase_document_access(p_type text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare v boolean;c boolean;e boolean;d boolean;begin
 perform asset_posting_private.identity();v:=purchase_order_private.allowed(p_type,'view');c:=purchase_order_private.allowed(p_type,'create');e:=purchase_order_private.allowed(p_type,'edit');d:=purchase_order_private.allowed(p_type,'delete');if not(v or c or e) then raise exception using errcode='42501',message='Sin acceso a este tipo de compra.';end if;return jsonb_build_object('canView',v,'canCreate',c,'canEdit',e,'canDelete',d,'canCreateNext',purchase_order_private.allowed(case p_type when 'REQUISITION' then 'QUOTE' when 'QUOTE' then 'ORDER' when 'ORDER' then 'RECEIPT' end,'create'));end$$;
create function public.purchase_workflow_options() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();o jsonb;k text;ok boolean:=false;begin
 foreach k in array array['REQUISITION','QUOTE','ORDER','RECEIPT'] loop ok:=ok or purchase_order_private.allowed(k,'view') or purchase_order_private.allowed(k,'create') or purchase_order_private.allowed(k,'edit');end loop;if not ok then raise exception using errcode='42501',message='Sin acceso a Compras.';end if;
 o:=purchase_order_private.purchase_workflow_options();
 return o||jsonb_build_object('sources',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(o->'sources') x where purchase_order_private.allowed(x->>'type','view') or purchase_order_private.allowed(case x->>'type' when 'REQUISITION' then 'QUOTE' when 'QUOTE' then 'ORDER' when 'ORDER' then 'RECEIPT' end,'create')),
 'accounts',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.chart_accounts a where not a.is_inactive and a.accepts_entries and exists(select 1 from public.account_subsidiaries s where s.account_id=a.account_id and s.subsidiary_id=sid and s.is_active)),
 'accountGroups',(select coalesce(jsonb_agg(to_jsonb(g)),'[]') from public.account_group g where exists(select 1 from public.chart_accounts a join public.account_subsidiaries s using(account_id) where a.account_group_id=g.group_id and s.subsidiary_id=sid and s.is_active)),
 'departments',(select coalesce(jsonb_agg(to_jsonb(d)),'[]') from public.departments d where not d.is_inactive and (d.subsidiary_id=sid or exists(select 1 from public.department_subsidiaries s where s.department_id=d.department_id and s.subsidiary_id=sid))),
 'costs',(select coalesce(jsonb_agg(to_jsonb(c)),'[]') from public.cost_centers c where c.subsidiary_id=sid and not c.is_inactive),
 'classes',(select coalesce(jsonb_agg(to_jsonb(c)),'[]') from public.classes c where not c.is_inactive and (c.subsidiary_id=sid or exists(select 1 from public.class_subsidiaries s where s.class_id=c.class_id and s.subsidiary_id=sid))),
 'customers',(select coalesce(jsonb_agg(jsonb_build_object('customer_id',c.customer_id,'department_id',c.department_id)),'[]') from public.customers c where exists(select 1 from public.entity_subsidiaries es where es.customer_id=c.customer_id and es.subsidiary_id=sid)));
end$$;
create function purchase_order_private.actions(id bigint) returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select jsonb_build_object('canEdit',x.editable and purchase_order_private.allowed(d.document_type,'edit'),'canDelete',x.editable and purchase_order_private.allowed(d.document_type,'delete') and not exists(select 1 from public.wf_instances where entity_type='PURCHASE_ORDER' and entity_id=$1),'canSubmit',d.document_type='ORDER' and x.editable and purchase_order_private.allowed('ORDER','edit')) from public.purchase_document d cross join lateral(select d.status in('BORRADOR','RECHAZADO') and not exists(select 1 from public.purchase_document where source_document_id=d.document_id) and not exists(select 1 from public.supplier_invoice where purchase_receipt_document_id=d.document_id or po_id=d.document_id) as editable)x where d.document_id=id$$;
create function public.purchase_document_report(p_filters jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;begin perform purchase_order_private.access(p_filters->>'type','view');r:=purchase_order_private.purchase_document_report(p_filters);return r||jsonb_build_object('rows',(select coalesce(jsonb_agg(x||jsonb_build_object('actions',purchase_order_private.actions((x->>'id')::bigint))),'[]') from jsonb_array_elements(r->'rows')x));end$$;
create function public.purchase_document_detail(p_document_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document%rowtype;editable boolean;begin
 d:=purchase_order_private.header(p_document_id,'view');editable:=d.status in('BORRADOR','RECHAZADO') and not exists(select 1 from public.purchase_document where source_document_id=d.document_id) and not exists(select 1 from public.supplier_invoice where purchase_receipt_document_id=d.document_id or po_id=d.document_id);
 return purchase_order_private.purchase_document_detail(p_document_id)||jsonb_build_object('actions',jsonb_build_object('canEdit',editable and purchase_order_private.allowed(d.document_type,'edit'),'canDelete',editable and purchase_order_private.allowed(d.document_type,'delete'),'canSubmit',d.document_type='ORDER' and editable and purchase_order_private.allowed('ORDER','edit')));end$$;
create function public.purchase_document_source(p_document_id bigint,p_type text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document%rowtype;sid bigint:=asset_posting_private.identity();begin
 if not(purchase_order_private.allowed(p_type,'create') or purchase_order_private.allowed(p_type,'edit')) then raise exception using errcode='42501',message='Sin permiso para usar documento origen.';end if;
 select * into d from public.purchase_document where document_id=p_document_id and subsidiary_id=sid;
 if d.document_id is null or d.document_type is distinct from (case p_type when 'QUOTE' then 'REQUISITION' when 'ORDER' then 'QUOTE' when 'RECEIPT' then 'ORDER' end) or d.status='CANCELADO' or (p_type='RECEIPT' and d.status<>'APROBADO') then raise exception using errcode='42501',message='Documento origen no disponible.';end if;
 return purchase_order_private.purchase_document_detail(p_document_id);end$$;
create function public.delete_purchase_document(p_document_id bigint) returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document%rowtype;begin
 d:=purchase_order_private.header(p_document_id,'delete');perform purchase_order_private.editable(d);
 if exists(select 1 from public.wf_instances where entity_type='PURCHASE_ORDER' and entity_id=d.document_id) then raise exception using errcode='55000',message='El documento conserva historial de aprobacion.';end if;
 return purchase_order_private.delete_purchase_document(p_document_id);end$$;
-- Submission context is reconstructed from the stored order, never from client routing overrides.
create function purchase_order_private.submit_access(id bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document%rowtype;p jsonb;begin
 d:=purchase_order_private.header(id,'edit');if d.document_type<>'ORDER' then raise exception using errcode='42501',message='Orden no disponible.';end if;perform purchase_order_private.editable(d);
 p:=jsonb_build_object('type','ORDER','date',d.document_date,'supplier_id',d.supplier_id,'currency_id',d.currency_id,'rate',d.exchange_rate,'period_id',d.fiscal_period_id,'location_id',d.location_id,'payment_term_id',d.payment_term_id,'source_id',d.source_document_id,'status','BORRADOR','lines',(select jsonb_agg(to_jsonb(l) order by l.line_number) from public.purchase_document_line l where l.document_id=id));
 perform purchase_order_private.prepare(p,id);
 if not asset_posting_private.finite(d.total_amount) or d.total_amount<=0 or d.total_amount is distinct from (select sum(gross_amount) from public.purchase_document_line where document_id=id) then raise exception using errcode='55000',message='Total de orden inconsistente.';end if;
end$$;
create function purchase_order_private.submit_engine(id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;old_guard text:=current_setting('nexo.purchase_order_id',true);begin
 perform purchase_order_private.submit_access(id);perform set_config('nexo.purchase_order_id',id::text,true);
 r:=payment_request_private.wf_start_entity_without_budget('PURCHASE_ORDER',id,'{}');
 if not exists(select 1 from public.wf_instance_steps where instance_id=(r->>'id')::bigint) then raise exception using errcode='55000',message='La orden requiere al menos un nivel de aprobacion aplicable.';end if;
 perform set_config('nexo.purchase_order_id',coalesce(old_guard,''),true);return r;end$$;
-- Guard budget dispatch itself, including the service-only compatibility RPC.
create function purchase_order_private.fingerprint(id bigint) returns text language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select md5(jsonb_build_object('header',to_jsonb(d),'lines',(select jsonb_agg(to_jsonb(l) order by l.line_number) from public.purchase_document_line l where l.document_id=$1))::text) from public.purchase_document d where d.document_id=$1$$;
do $$declare body text;modified text;begin body:=pg_get_functiondef('public.budget_run(text,jsonb,bigint)'::regprocedure);
 modified:=replace(body,'begin'||chr(10),'begin'||chr(10)||' if p_type=''ORD_COM'' then perform purchase_order_private.prepare(p_payload,p_id);elsif p_type=''WORKFLOW_START'' and p_payload->>''entityType''=''PURCHASE_ORDER'' then perform purchase_order_private.submit_access(p_id);p_payload:=jsonb_build_object(''entityType'',''PURCHASE_ORDER'',''context'',jsonb_build_object(''orderFingerprint'',purchase_order_private.fingerprint(p_id)));end if;'||chr(10));
 modified:=regexp_replace(modified,'(?<![a-zA-Z0-9_.])(?:public\.)?save_purchase_document_without_budget\(p_payload,p_id\)','purchase_order_private.engine(p_payload,p_id)','g');
 modified:=replace(modified,'else result:=wf_start_entity_without_budget(p_payload->>''entityType'',p_id,coalesce(p_payload->''context'',''{}''));','elsif p_payload->>''entityType''=''PURCHASE_ORDER'' then result:=purchase_order_private.submit_engine(p_id);else result:=wf_start_entity_without_budget(p_payload->>''entityType'',p_id,coalesce(p_payload->''context'',''{}''));');
 if position('purchase_order_private.engine(p_payload,p_id)' in modified)=0 or position('purchase_order_private.submit_engine(p_id)' in modified)=0 then raise exception 'Unexpected purchase budget dispatcher';end if;execute modified;end$$;
-- Keep previous payment-request wrappers intact behind these order-specific checks.
alter function public.wf_act(bigint,text,text,inet) set schema purchase_order_private;
alter function public.wf_instance_detail(text,bigint) set schema purchase_order_private;
alter function public.wf_start_entity_without_budget(text,bigint,jsonb) set schema purchase_order_private;
alter function public.wf_apply_entity_status(text,bigint,text) set schema purchase_order_private;
alter function public.wf_apply_entity_status_without_budget(text,bigint,text) set schema purchase_order_private;
alter function public.wf_entity_data(text,bigint) set schema purchase_order_private;
alter function public.wf_entity_data_without_budget(text,bigint) set schema purchase_order_private;
create function public.wf_act(p_instance_id bigint,p_action text,p_comment text default null,p_ip inet default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare i public.wf_instances;d public.purchase_document;old_guard text:=current_setting('nexo.purchase_order_id',true);r jsonb;begin
 perform asset_posting_private.identity();select * into i from public.wf_instances where id=p_instance_id for update;
 if i.entity_type='PURCHASE_ORDER' then
  d:=purchase_order_private.header(i.entity_id,case upper(p_action) when 'CANCELAR' then 'delete' else 'view' end);
  if d.document_type<>'ORDER' or i.subsidiaria_id<>d.subsidiary_id or i.status<>'EN_REVISION' or d.status<>'PENDIENTE_APROBACION' or i.amount is distinct from d.total_amount then raise exception using errcode='55000',message='Orden o aprobacion protegida por estado o importe.';end if;
  if upper(p_action) in('APROBAR','RECHAZAR') and not public.app_is_admin() and not exists(select 1 from public.wf_instance_steps s where s.instance_id=i.id and s.nivel=i.current_level and s.status='PENDIENTE' and (s.usuario_aprobador_id=public.app_user_id() or s.rol_aprobador_id=public.app_active_role_id())) then raise exception using errcode='42501',message='El rol activo no esta asignado a este nivel.';end if;
  if upper(p_action) in('RECHAZAR','CANCELAR') and nullif(trim(p_comment),'') is null then raise exception using errcode='22023',message='Indique el motivo.';end if;
  perform set_config('nexo.purchase_order_id',d.document_id::text,true);
 end if;
 r:=purchase_order_private.wf_act(p_instance_id,p_action,p_comment,p_ip);perform set_config('nexo.purchase_order_id',coalesce(old_guard,''),true);return r;end$$;
create function public.wf_instance_detail(p_entity_type text,p_entity_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if p_entity_type='PURCHASE_ORDER' and not purchase_order_private.visible(p_entity_id) then raise exception using errcode='42501',message='Orden no disponible.';end if;return purchase_order_private.wf_instance_detail(p_entity_type,p_entity_id);end$$;
create function public.wf_start_entity_without_budget(p_entity_type text,p_entity_id bigint,p_context jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_entity_type='PURCHASE_ORDER' then raise exception using errcode='42501',message='Use el envio con control presupuestario.';end if;return purchase_order_private.wf_start_entity_without_budget(p_entity_type,p_entity_id,p_context);end$$;
create function public.wf_apply_entity_status(p_type text,p_id bigint,p_status text) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PURCHASE_ORDER' then raise exception using errcode='42501',message='El estado requiere una decision del flujo.';end if;perform purchase_order_private.wf_apply_entity_status(p_type,p_id,p_status);end$$;
create function public.wf_apply_entity_status_without_budget(p_type text,p_id bigint,p_status text) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PURCHASE_ORDER' then raise exception using errcode='42501',message='El estado requiere una decision del flujo.';end if;perform purchase_order_private.wf_apply_entity_status_without_budget(p_type,p_id,p_status);end$$;
create function public.wf_entity_data(p_type text,p_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PURCHASE_ORDER' and not purchase_order_private.visible(p_id) then raise exception using errcode='42501',message='Orden no disponible.';end if;return purchase_order_private.wf_entity_data(p_type,p_id);end$$;
create function public.wf_entity_data_without_budget(p_type text,p_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PURCHASE_ORDER' and not purchase_order_private.visible(p_id) then raise exception using errcode='42501',message='Orden no disponible.';end if;return purchase_order_private.wf_entity_data_without_budget(p_type,p_id);end$$;
do $$declare body text;begin body:=pg_get_functiondef('public.wf_inbox()'::regprocedure);if position('where (i.entity_type' in body)=0 then raise exception 'Unexpected Workflow inbox';end if;execute replace(body,'where (i.entity_type','where (i.entity_type<>''PURCHASE_ORDER'' or (purchase_order_private.visible(i.entity_id) and (s.usuario_aprobador_id=public.app_user_id() or s.rol_aprobador_id=public.app_active_role_id() or public.app_is_admin()))) and (i.entity_type');end$$;
create function purchase_order_private.status_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if old.document_type='ORDER' and new.status is distinct from old.status and coalesce(current_setting('nexo.purchase_order_id',true),'')<>old.document_id::text then raise exception using errcode='42501',message='El estado de la orden requiere el flujo autorizado.';end if;return new;end$$;
create trigger purchase_order_status_guard before update on public.purchase_document for each row execute function purchase_order_private.status_guard();
do $$declare t text;p record;c record;begin foreach t in array array['purchase_document','purchase_document_line','purchase_order'] loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);for c in select column_name from information_schema.columns where table_schema='public' and table_name=t loop execute format('revoke all (%I) on public.%I from public,anon,authenticated,service_role',c.column_name,t);end loop;
 execute format('grant select on public.%I to authenticated',t);execute format('create policy purchase_order_read on public.%I for select to authenticated using(%s)',t,case when t='purchase_order' then 'subsidiary_id=asset_posting_private.identity() and purchase_order_private.allowed(''ORDER'',''view'')' else 'purchase_order_private.visible(document_id)' end);
end loop;end$$;
revoke all on all functions in schema purchase_order_private from public,anon,authenticated,service_role;
grant execute on function purchase_order_private.visible(bigint),purchase_order_private.allowed(text,text) to authenticated;
revoke all on function public.purchase_document_access(text),public.purchase_workflow_options(),public.purchase_document_report(jsonb),public.purchase_document_detail(bigint),public.purchase_document_source(bigint,text),public.save_purchase_document(jsonb,bigint),public.delete_purchase_document(bigint),public.wf_act(bigint,text,text,inet),public.wf_instance_detail(text,bigint),public.wf_start_entity_without_budget(text,bigint,jsonb),public.wf_apply_entity_status(text,bigint,text),public.wf_apply_entity_status_without_budget(text,bigint,text),public.wf_entity_data(text,bigint),public.wf_entity_data_without_budget(text,bigint),public.validate_purchase_document_header_scope(),public.validate_purchase_document_line_scope(),public.wf_protect_purchase_order() from public,anon,authenticated,service_role;
grant execute on function public.purchase_document_access(text),public.purchase_workflow_options(),public.purchase_document_report(jsonb),public.purchase_document_detail(bigint),public.purchase_document_source(bigint,text),public.save_purchase_document(jsonb,bigint),public.delete_purchase_document(bigint),public.wf_act(bigint,text,text,inet),public.wf_instance_detail(text,bigint) to authenticated;
grant execute on function public.wf_act(bigint,text,text,inet),public.wf_instance_detail(text,bigint),public.wf_start_entity_without_budget(text,bigint,jsonb),public.wf_apply_entity_status(text,bigint,text),public.wf_apply_entity_status_without_budget(text,bigint,text),public.wf_entity_data(text,bigint),public.wf_entity_data_without_budget(text,bigint) to service_role;
notify pgrst,'reload schema';
